-- verify (SELECT only)
-- generated by scripts/prod-open/sat-expand-sql.ts. Run: npx supabase db query --linked -f <this file>. Idempotent; no deletes/overwrites; nothing is published here (drafts only).

select s.name, s.version_no, s.status, s.readiness_status, (select count(*) from mock_exam_set_items i where i.exam_set_id = s.id) as items from mock_exam_sets s where s.status = 'draft' and s.archived_at is null order by length(s.name), s.name;
select (select count(*) from problem_versions where quality->'mockExamGeneration'->>'gid' ~ '^(sx|sy|sz)-') as r_w_imported, (select count(*) from problem_versions where quality->'mockExamGeneration'->>'gid' ~ '^e1018-') as slot_replacements,
       (select count(*) from problem_versions where quality->'auditFix'->>'patch' like 'E1018-%') as patch_versions, (select count(*) from mock_exam_sets where status = 'published' and archived_at is null) as published_sets_unchanged;
select s.name, count(*) filter (where p.published_version_id is distinct from i.problem_version_id) as stale_items from mock_exam_sets s join mock_exam_set_items i on i.exam_set_id = s.id join problems p on p.id = i.problem_id where s.status = 'draft' and s.archived_at is null group by s.name order by 1;
